INSERT IGNORE INTO class_enrollments (offering_id, child_id, enrolled_by_user_id) SELECT co.id, c.id, mu.id FROM class_offerings co JOIN children c ON c.program_track = co.program_track JOIN users mu ON mu.username = 'manager1' WHERE RIGHT(c.child_name, 1) = 'A';
INSERT INTO parent_notes (child_id, author_user_id, note_text) SELECT c.id, u.id, 'Great focus in class this week. Keep practicing your form at home.' FROM children c JOIN users u ON u.username = 'employee3' WHERE c.child_name = 'KMA_White_A' AND NOT EXISTS (SELECT 1 FROM parent_notes pn WHERE pn.child_id = c.id AND pn.note_text = 'Great focus in class this week. Keep practicing your form at home.');
INSERT INTO parent_notes (child_id, author_user_id, note_text) SELECT c.id, u.id, 'Excellent consistency and strong attendance. Ready for added challenge.' FROM children c JOIN users u ON u.username = 'employee6' WHERE c.child_name = 'AMA_BlackBelt_A' AND NOT EXISTS (SELECT 1 FROM parent_notes pn WHERE pn.child_id = c.id AND pn.note_text = 'Excellent consistency and strong attendance. Ready for added challenge.');
INSERT INTO staff_weekly_connections (user_id, week_start_date, connection_text) SELECT u.id, DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY), 'Weekly connection from employee1: student engagement focus area #1.' FROM users u WHERE u.username = 'employee1' ON DUPLICATE KEY UPDATE connection_text = VALUES(connection_text);
